from pathlib import Path
import csv,gzip,html,json,statistics
root=Path('.').resolve();out=root/'output/followup_analysis'
def read(p):
 with (gzip.open(p,'rt') if str(p).endswith('.gz') else open(p)) as h:return list(csv.DictReader(h,delimiter='\t'))
def write(p,r,fields=None):
 with open(p,'w') as h:
  w=csv.DictWriter(h,fieldnames=fields or list(r[0]),delimiter='\t');w.writeheader();w.writerows(r)
def esc(s):return html.escape(str(s))
def table(rows,cols=None):
 if not rows:return '<p>No rows.</p>'
 cols=cols or list(rows[0]);return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(c)+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(r.get(c,''))+'</td>' for c in cols)+'</tr>' for r in rows)+'</tbody></table></div>'
def fm(x):
 try:return f'{float(x):.4g}'
 except:return x
def small(p,cols=None):
 rows=read(p);return table([{k:fm(v) for k,v in r.items()} for r in rows],cols)
