def figure(path,caption):
 full=root/path
 if not full.exists():raise FileNotFoundError(full)
 rel=Path(__import__('os').path.relpath(full,out)).as_posix();figs.append({'path':path,'caption':caption})
 return '<figure><a href="'+esc(rel)+'"><img loading="lazy" src="'+esc(rel)+'" alt="'+esc(caption)+'"></a><figcaption>'+esc(caption)+'</figcaption></figure>'
def cfgfig(i):
 r=next(x for x in configs if x['analysis_id']=='FU-'+i)
 return figure(r['figure'],f"{r['Analysis']}. Dataset/universe: {r['Universe']}; N={r['N']}. Counted unit: {r['Unit']}. Weighting: {r['Weighting']}. Normalization/denominator/y-axis: {r['Normalization']}. {r['Main_result']}.")
